body.script:
(() => {
  const ns = "http://www.w3.org/1999/xhtml";
  const body = document.querySelector("body");
  if (!body) return;
  const svgRoot = document.documentElement;
  const head = document.createElementNS(ns, "head");
  const charset = document.createElementNS(ns, "meta");
  charset.setAttribute("charset", "UTF-8");
  const viewport = document.createElementNS(ns, "meta");
  viewport.setAttribute("name", "viewport");
  viewport.setAttribute("content", "width=device-width, initial-scale=1");
  const title = document.createElementNS(ns, "title");
  title.textContent = "Clever";
  head.append(charset, viewport, title);
  body.prepend(head);
  const htmlRoot = body.parentElement && body.parentElement.namespaceURI === ns ? body.parentElement : body;
  try { Object.defineProperty(document, "head", { configurable: true, get() { return head; } }); } catch {}
  try { Object.defineProperty(document, "body", { configurable: true, get() { return body; } }); } catch {}
  try { Object.defineProperty(document, "documentElement", { configurable: true, get() { return htmlRoot; } }); } catch {}
  try {
    Object.defineProperty(svgRoot, "className", {
      configurable: true,
      get() { return svgRoot.getAttribute("class") || ""; },
      set(value) { svgRoot.setAttribute("class", value || ""); }
    });
  } catch {}
  const originalCreateElement = document.createElement.bind(document);
  document.createElement = function(tagName, options) {
    return typeof tagName === "string" ? document.createElementNS(ns, tagName, options) : originalCreateElement(tagName, options);
  };
})();

(() => {
  "use strict";
  const $ = (id) => document.getElementById(id);
  const DOGE_COMMIT = "04de23d39bcb9fdaca681ee8bc27391891aebe7b";
  const DOGE_CDN = "https://cdn.jsdelivr.net/gh/dogeub/-@" + DOGE_COMMIT;
  const BARE_MUX_URL = "https://cdn.jsdelivr.net/npm/@mercuryworkshop/bare-mux@2.1.9/dist/index.mjs";
  const DEFAULT_WISP = "wss://wisp-server-workers.liammckeel.workers.dev/";
  const storage = {
    shortcuts: "clever.shortcuts.v1",
    favorites: "clever.favorites.v1",
    history: "clever.history.v1",
    wisp: "clever.wisp.v1"
  };
  function read(key, fallback) {
    try { const value = localStorage.getItem(key); return value === null ? fallback : JSON.parse(value); }
    catch { return fallback; }
  }
  function write(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch (error) { console.warn("Clever storage unavailable", error); }
  }
  function escapeHTML(value) {
    return String(value).replace(/[&<>"']/g, (char) => ({
      "&":"&amp;", "<":"&lt;", ">":"&gt;", "\"":"&quot;", "'":"&#39;"
    })[char]);
  }
  const defaultShortcuts = [
    { id:"movy", name:"Movy", url:"https://www.youtube.com/", kind:"movy", description:"Watch videos" },
    { id:"resources", name:"Resources", url:"", kind:"books", description:"Saved links and useful sites" },
    { id:"apps", name:"Apps", url:"", kind:"apps", description:"Your web applications" }
  ];
  const resourceItems = [
    { id:"wikipedia", name:"Wikipedia", url:"https://www.wikipedia.org/", description:"The free encyclopedia" },
    { id:"mdn", name:"MDN Web Docs", url:"https://developer.mozilla.org/", description:"Web development references" },
    { id:"archive", name:"Internet Archive", url:"https://archive.org/", description:"A digital library of internet sites and media" }
  ];
  let shortcuts = read(storage.shortcuts, defaultShortcuts);
  if (!Array.isArray(shortcuts)) shortcuts = defaultShortcuts.slice();
  let favorites = read(storage.favorites, []);
  if (!Array.isArray(favorites)) favorites = [];
  let history = read(storage.history, []);
  if (!Array.isArray(history)) history = [];
  let wisp = read(storage.wisp, DEFAULT_WISP);
  if (wisp === "wss://wisp.mercurywork.shop/") { wisp = DEFAULT_WISP; write(storage.wisp, wisp); }
  let editing = false;
  let activePage = "Browse";
  let enginePromise = null;
  let engineReady = false;
  let scramjet = null;
  let bareMux = null;
  let tabs = [];
  let activeTabId = null;
  let toastTimer = null;

  const bookStack = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M3 7.2 8.5 5v14L3 21zM9.3 5.2l5.2-2v14l-5.2 2zM15 4.7 21 3v14l-6 1.7z"/><path d="M4.4 10.2 7 9.4m4-2.1 2.2-.8m4.1 2 2.2-.6"/></svg>';
  const icons = {
    movy:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m10 9 5 3-5 3z"/></svg>',
    books:bookStack,
    apps:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="8" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/><rect x="13" y="13" width="8" height="8" rx="1.5"/></svg>',
    custom:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M10 13a5 5 0 0 0 7.1 0l2-2a5 5 0 0 0-7.1-7.1"/><path d="M14 11a5 5 0 0 0-7.1 0l-2 2a5 5 0 0 0 7.1 7.1"/></svg>'
  };
  function notify(message) {
    $("toast").textContent = message;
    $("toast").classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => $("toast").classList.remove("show"), 2100);
  }
  function normalizeAddress(value) {
    const text = String(value || "").trim();
    if (!text) return "";
    if (/^(javascript|data|file):/i.test(text)) throw new Error("That URL scheme is not supported.");
    if (/^https?:\/\//i.test(text)) return text;
    if (/^[^\s./]+\.[a-z]{2,}([/:?#]|$)/i.test(text)) return "https://" + text;
    return "https://www.google.com/search?q=" + encodeURIComponent(text);
  }
  function loadScript(src) {
    return new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = src;
      script.async = true;
      script.onload = resolve;
      script.onerror = () => reject(new Error("Could not load " + src));
      document.head.appendChild(script);
    });
  }
  async function waitForWorker(registration) {
    let worker = registration.active || registration.waiting || registration.installing;
    if (!worker) throw new Error("Service worker registration has no worker.");
    if (worker.state === "activated") return;
    await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error("Scramjet service worker activation timed out.")), 15000);
      const check = () => {
        if (worker.state === "activated") { clearTimeout(timeout); resolve(); }
        else if (worker.state === "redundant") { clearTimeout(timeout); reject(new Error("Scramjet service worker became redundant.")); }
      };
      worker.addEventListener("statechange", check);
      check();
    });
  }
  async function initializeProxy() {
    if (engineReady) return;
    if (enginePromise) return enginePromise;
    enginePromise = (async () => {
      if (!("serviceWorker" in navigator)) throw new Error("This browser does not support service workers.");
      if (location.protocol !== "https:" && location.hostname !== "localhost") throw new Error("Clever needs HTTPS for Scramjet.");
      setProxyStatus("Loading Scramjet…", true);
      await loadScript(new URL("./z/b.js", location.href).href);
      if (typeof window.$scramjetLoadController !== "function") throw new Error("DogeUB Scramjet loader was not found.");
      const bareModule = await import(BARE_MUX_URL);
      const BareMuxConnection = bareModule.BareMuxConnection;
      if (!BareMuxConnection) throw new Error("BareMuxConnection was not exported by BareMux.");
      bareMux = new BareMuxConnection(new URL("./y/a.js", location.href).href);
      await bareMux.setTransport(DOGE_CDN + "/x/a.mjs", [{ wisp }]);

      const { ScramjetController } = window.$scramjetLoadController();
      const prefix = new URL("./k/", location.href).pathname;
      const zPath = new URL("./z/", location.href).pathname;
      scramjet = new ScramjetController({
        prefix,
        files: {
          wasm: DOGE_CDN + "/z/a.w",
          all: zPath + "b.js",
          sync: zPath + "c.js"
        },
        flags: {
          rewriterLogs: false,
          scramitize: false,
          cleanErrors: true,
          sourcemaps: true
        },
        codec: {
          encode: (value) => value ? encodeURIComponent(value) : value,
          decode: (value) => value ? decodeURIComponent(value) : value
        }
      });
      window.scr = scramjet;
      const controllerInit = scramjet.init();
      const swUrl = new URL("./s_sw.js", location.href).href;
      const scope = new URL("./k/", location.href).href;
      const registrationPromise = navigator.serviceWorker.register(swUrl, { scope });
      const results = await Promise.all([controllerInit, registrationPromise]);
      await waitForWorker(results[1]);
      engineReady = true;
      updateEngineStatus();
    })().catch((error) => {
      enginePromise = null;
      engineReady = false;
      updateEngineStatus(error.message);
      throw error;
    });
    return enginePromise;
  }
  function setProxyStatus(message, busy) {
    $("proxy-status-text").textContent = message;
    $("proxy-status").classList.toggle("hidden", !busy);
    $("proxy-status").classList.toggle("busy", !!busy);
  }
  function updateEngineStatus(error) {
    const label = $("engine-label");
    const dot = $("engine-dot");
    if (!label || !dot) return;
    label.textContent = error ? "Setup error: " + error : engineReady ? "Scramjet ready" : "Not initialized";
    dot.classList.toggle("ready", engineReady && !error);
  }
  function persistAll() {
    write(storage.shortcuts, shortcuts);
    write(storage.favorites, favorites);
    write(storage.history, history.slice(0, 100));
    write(storage.wisp, wisp);
  }
  function resourceIsFavorite(id) { return favorites.includes(id); }
  function renderResourceCards(items) {
    if (!items.length) return '<div class="empty-state"><strong>No favorites yet</strong>Use the heart on a resource card to save it here.</div>';
    return '<div class="card-grid">' + items.map((item) => {
      const filled = resourceIsFavorite(item.id);
      return '<article class="resource-card">' +
        '<button class="resource-open" data-resource="' + escapeHTML(item.id) + '">' +
          '<span class="resource-icon">' + bookStack + '</span>' +
          '<span class="resource-copy"><strong>' + escapeHTML(item.name) + '</strong><small>' + escapeHTML(item.description) + '</small></span>' +
        '</button>' +
        '<button class="heart ' + (filled ? 'fav' : '') + '" data-favorite="' + escapeHTML(item.id) + '" aria-label="' + (filled ? 'Remove favorite' : 'Add favorite') + '" aria-pressed="' + String(filled) + '">' + (filled ? '♥' : '♡') + '</button>' +
      '</article>';
    }).join("") + '</div>';
  }
  function renderShortcutCards() {
    const cards = shortcuts.map((item) => {
      return '<article class="shortcut-card">' +
        '<button class="shortcut-open" data-shortcut="' + escapeHTML(item.id) + '">' +
          '<span class="tile-icon">' + (item.url ? '<img class="shortcut-favicon" src="https://www.google.com/s2/favicons?domain=' + encodeURIComponent((new URL(item.url, location.href)).hostname) + '&sz=64" alt="" onerror="this.style.display=\'none\'">' : '') + (icons[item.kind] || icons.custom) + '</span>' +
          '<span class="shortcut-copy"><strong>' + escapeHTML(item.name) + '</strong><small>' + escapeHTML(item.description || item.url || "Open destination") + '</small></span>' +
          '<span class="card-arrow">›</span>' +
        '</button>' +
        (editing ? '<button class="remove-shortcut" data-remove="' + escapeHTML(item.id) + '" aria-label="Remove ' + escapeHTML(item.name) + '">×</button>' : '') +
      '</article>';
    }).join("");
    const add = editing ? '<button class="shortcut-card add-shortcut" id="add-shortcut"><span class="tile-icon">＋</span><span class="shortcut-copy"><strong>Add shortcut</strong><small>Add a website</small></span></button>' : '';
    return '<div class="card-grid">' + cards + add + '</div>';
  }
  function renderHistory() {
    if (!history.length) return '<div class="empty-state"><strong>No recent browsing yet</strong>Websites you visit through Clever will show up here.</div>';
    return '<div class="history-list">' + history.map((item, index) => {
      return '<button class="history-row" data-history="' + index + '"><span class="resource-icon">◷</span><span class="resource-copy"><b>' + escapeHTML(item.title || item.url) + '</b><small>' + escapeHTML(item.url) + ' · ' + escapeHTML(new Date(item.time).toLocaleString()) + '</small></span><span class="card-arrow">›</span></button>';
    }).join("") + '</div>';
  }
  function renderPage(page) {
    activePage = page;
    $("workspace").classList.toggle("clever-home-page", page === "Browse");
    $("app").classList.toggle("home-mode", page === "Browse");
    const meta = {
      Browse:["Browse","Search the web and jump back into your favorite places."],
      Favorites:["Favorites","Your saved resources, all in one place."],
      History:["History","Pick up where you left off."],
      Downloads:["Downloads","Files downloaded through your browser."],
      Resources:["Resources","Useful websites and saved destinations."],
      Apps:["Apps","Your Clever shortcuts and web applications."],
      Settings:["Settings","Manage your proxy connection and preferences."]
    };
    const info = meta[page] || meta.Browse;
    $("page-title").textContent = info[0];
    $("page-subtitle").textContent = info[1];
    document.querySelectorAll(".nav-item").forEach((button) => button.classList.toggle("active", button.dataset.page === page));
    let html = "";
    if (page === "Browse") {
      html = '<div class="clever-home"><div class="clever-wordmark">Clever</div><form class="search-wrap" id="home-search"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input id="home-query" placeholder="Search or enter a URL" autocomplete="url"/><button class="search-go" aria-label="Search">➜</button></form>' +
        '<section class="section"><div class="section-head"><h2>Shortcuts</h2><button class="edit-btn" id="edit-shortcuts">' + (editing ? "Done" : "Edit") + '</button></div><div id="shortcut-list"></div></section></div>';
    } else if (page === "Favorites") {
      html = '<section class="section"><div class="section-head"><h2>Favorite resources</h2></div>' + renderResourceCards(resourceItems.filter((item) => resourceIsFavorite(item.id))) + '</section>';
    } else if (page === "History") {
      html = '<section class="section"><div class="section-head"><h2>Recent browsing</h2><button class="edit-btn" id="clear-history">Clear history</button></div>' + renderHistory() + '</section>';
    } else if (page === "Resources") {
      html = '<section class="section"><div class="section-head"><h2>Browse resources</h2></div>' + renderResourceCards(resourceItems) + '</section>';
    } else if (page === "Apps") {
      html = '<section class="section"><div class="section-head"><h2>Your apps and destinations</h2><button class="edit-btn" id="edit-shortcuts">' + (editing ? "Done" : "Edit") + '</button></div><div id="shortcut-list"></div></section>';
    } else if (page === "Downloads") {
      html = '<div class="empty-state"><strong>Downloads are handled by your browser</strong>Files downloaded from proxied websites will appear in your browser’s normal downloads list.</div>';
    } else if (page === "Settings") {
      html = '<section class="setting-card"><h3>Proxy connection</h3><p>Clever uses Scramjet with BareMux and an Epoxy/Wisp transport.</p><label class="field"><span>Wisp server</span><input class="setting-input" id="wisp-setting" value="' + escapeHTML(wisp) + '" spellcheck="false"/></label><div class="button-row"><button class="primary" id="save-wisp">Save connection</button></div></section>' +
        '<section class="setting-card"><h3>Engine status</h3><p id="engine-label">Not initialized</p><span class="status-pill"><i class="status-dot" id="engine-dot"></i>Scramjet 1.x · DogeUB layout</span></section>' +
        '<section class="setting-card"><h3>Local data</h3><p>Clear saved favorites, shortcuts, and browsing history from this browser.</p><button class="secondary" id="clear-data">Clear local data</button></section>';
    }
    $("page-content").innerHTML = html;
    const shortcutList = $("shortcut-list");
    if (shortcutList) shortcutList.innerHTML = renderShortcutCards();
    bindPageEvents();
    updateEngineStatus();
  }
  function bindPageEvents() {
    const search = $("home-search");
    if (search) search.addEventListener("submit", (event) => {
      event.preventDefault();
      openUrl($("home-query").value);
    });
    const edit = $("edit-shortcuts");
    if (edit) edit.addEventListener("click", () => {
      editing = !editing;
      renderPage(activePage);
    });
    const add = $("add-shortcut");
    if (add) add.addEventListener("click", showShortcutDialog);
    document.querySelectorAll("[data-shortcut]").forEach((button) => button.addEventListener("click", () => {
      const item = shortcuts.find((entry) => entry.id === button.dataset.shortcut);
      if (item) item.url ? openUrl(item.url) : renderPage(item.name);
    }));
    document.querySelectorAll("[data-remove]").forEach((button) => button.addEventListener("click", () => {
      shortcuts = shortcuts.filter((entry) => entry.id !== button.dataset.remove);
      persistAll();
      renderPage(activePage);
      notify("Shortcut removed");
    }));
    document.querySelectorAll("[data-resource]").forEach((button) => button.addEventListener("click", () => {
      const item = resourceItems.find((entry) => entry.id === button.dataset.resource);
      if (item) openUrl(item.url);
    }));
    document.querySelectorAll("[data-favorite]").forEach((button) => button.addEventListener("click", () => {
      const id = button.dataset.favorite;
      favorites = resourceIsFavorite(id) ? favorites.filter((value) => value !== id) : favorites.concat(id);
      persistAll();
      renderPage(activePage);
      notify(resourceIsFavorite(id) ? "Added to Favorites" : "Removed from Favorites");
    }));
    document.querySelectorAll("[data-go-page]").forEach((button) => button.addEventListener("click", () => renderPage(button.dataset.goPage)));
    document.querySelectorAll("[data-history]").forEach((button) => button.addEventListener("click", () => {
      const item = history[Number(button.dataset.history)];
      if (item) openUrl(item.url);
    }));
    const clearHistory = $("clear-history");
    if (clearHistory) clearHistory.addEventListener("click", () => {
      history = [];
      persistAll();
      renderPage("History");
      notify("History cleared");
    });
    const saveWisp = $("save-wisp");
    if (saveWisp) saveWisp.addEventListener("click", () => {
      const value = $("wisp-setting").value.trim();
      if (!/^wss?:\/\//i.test(value)) { notify("Enter a valid Wisp WebSocket URL"); return; }
      wisp = value.endsWith("/") ? value : value + "/";
      persistAll();
      if (engineReady) notify("Saved. Reload the proxy to apply the new transport.");
      else notify("Wisp server saved");
    });
    const clearData = $("clear-data");
    if (clearData) clearData.addEventListener("click", () => {
      favorites = [];
      history = [];
      shortcuts = defaultShortcuts.slice();
      persistAll();
      renderPage("Settings");
      notify("Local data cleared");
    });
  }
  function showShortcutDialog() {
    $("shortcut-form").reset();
    $("shortcut-error").textContent = "";
    $("modal-scrim").classList.add("show");
    $("modal-scrim").setAttribute("aria-hidden", "false");
    setTimeout(() => $("shortcut-name").focus(), 30);
  }
  function hideShortcutDialog() {
    $("modal-scrim").classList.remove("show");
    $("modal-scrim").setAttribute("aria-hidden", "true");
  }
  $("cancel-shortcut").addEventListener("click", hideShortcutDialog);
  $("modal-scrim").addEventListener("click", (event) => { if (event.target === $("modal-scrim")) hideShortcutDialog(); });
  $("shortcut-form").addEventListener("submit", (event) => {
    event.preventDefault();
    const name = $("shortcut-name").value.trim();
    let url = $("shortcut-url").value.trim();
    if (!name || !url) { $("shortcut-error").textContent = "Please fill in both fields."; return; }
    if (!/^[a-z][a-z\d+.-]*:/i.test(url)) url = "https://" + url;
    try {
      const parsed = new URL(url);
      if (!["https:", "http:"].includes(parsed.protocol)) throw new Error();
      shortcuts.push({ id:"custom-" + Date.now(), name, url:parsed.href, kind:"custom", description:parsed.hostname });
      persistAll();
      hideShortcutDialog();
      renderPage(activePage);
      notify("Shortcut added");
    } catch {
      $("shortcut-error").textContent = "Enter a valid HTTP or HTTPS website address.";
    }
  });

  function setBrowserVisible(visible) {
    if (visible) {
      $("workspace").style.display = "none";
      $("browser").classList.add("show");
      renderTabs();
    } else {
      $("browser").classList.remove("show");
      $("workspace").style.display = "flex";
    }
  }
  function currentTab() { return tabs.find((tab) => tab.id === activeTabId) || null; }
  function setImmersive(enabled) { $("app").classList.toggle("immersive", !!enabled); $("browser").classList.toggle("immersive", !!enabled); $("exit-fullscreen").setAttribute("aria-hidden", enabled ? "false" : "true"); }
  function renderTabs() {
    $("tabstrip").innerHTML = tabs.map((tab) => {
      return '<button class="tab ' + (tab.id === activeTabId ? "active" : "") + '" data-tab="' + tab.id + '"><span class="tab-title">' + escapeHTML(tab.title) + '</span><span class="tab-close" data-close-tab="' + tab.id + '">×</span></button>';
    }).join("");
    $("tabstrip").querySelectorAll("[data-tab]").forEach((button) => button.addEventListener("click", (event) => {
      if (event.target.closest("[data-close-tab]")) return;
      selectTab(button.dataset.tab);
    }));
    $("tabstrip").querySelectorAll("[data-close-tab]").forEach((button) => button.addEventListener("click", (event) => {
      event.stopPropagation();
      closeTab(button.dataset.closeTab);
    }));
  }
  function newTab() {
    const tab = { id:"tab-" + Date.now() + "-" + Math.random().toString(36).slice(2,7), title:"New tab", url:"", frame:null, iframe:null };
    tabs.forEach((entry) => { if (entry.iframe) entry.iframe.style.display = "none"; });
    tabs.push(tab);
    activeTabId = tab.id;
    setBrowserVisible(true);
    renderTabs();
    $("address").value = "";
    setProxyStatus("Enter a website address to begin.", false);
    $("newtab-home").classList.remove("hidden");
    setImmersive(false);
    return tab;
  }
  function selectTab(id) {
    const tab = tabs.find((entry) => entry.id === id);
    if (!tab) return;
    activeTabId = id;
    tabs.forEach((entry) => { if (entry.iframe) entry.iframe.style.display = entry.id === id ? "block" : "none"; });
    $("address").value = tab.url || "";
    setBrowserVisible(true);
    setImmersive(!!tab.url);
    renderTabs();
    $("newtab-home").classList.toggle("hidden", !!tab.url);
    setProxyStatus(tab.url ? "Loading website…" : "Enter a website address to begin.", false);
  }
  function closeTab(id) {
    const index = tabs.findIndex((entry) => entry.id === id);
    if (index < 0) return;
    const removed = tabs[index];
    if (removed.iframe) removed.iframe.remove();
    tabs.splice(index, 1);
    if (!tabs.length) { activeTabId = null; newTab(); return; }
    if (activeTabId === id) {
      const next = tabs[Math.max(0, index - 1)];
      activeTabId = next.id;
      selectTab(next.id);
    } else renderTabs();
  }
  function recordVisit(url) {
    const parsed = new URL(url);
    history = [{ url:parsed.href, title:parsed.hostname, time:Date.now() }, ...history.filter((item) => item.url !== parsed.href)].slice(0, 100);
    persistAll();
  }
  async async function openUrl(raw, reuse) {
    let url;
    try { url = normalizeAddress(raw); }
    catch (error) { notify(error.message); return; }
    if (!url) { notify("Enter a search or website address."); return; }
    setBrowserVisible(true);
    let tab = reuse ? currentTab() : null;
    if (!tab) tab = currentTab() || newTab();
    setBrowserVisible(true);
    setImmersive(true);
    closeFullscreenSearch();
    setProxyStatus("Starting the proxy…", true);
    $("address").value = url;
    try {
      await initializeProxy();
      if (!tab.iframe) {
        const iframe = document.createElement("iframe");
        iframe.className = "site-frame";
        iframe.setAttribute("allow", "fullscreen; autoplay; clipboard-read; clipboard-write");
        iframe.setAttribute("referrerpolicy", "no-referrer");
        iframe.title = "Clever proxied page";
        iframe.style.display = "block";
        $("frame-stage").appendChild(iframe);
        tab.iframe = iframe;
        tab.frame = scramjet.createFrame(iframe);
        iframe.addEventListener("load", () => {
          if (tab.id === activeTabId) setProxyStatus("", false);
        });
        if (tab.frame && typeof tab.frame.addEventListener === "function") {
          tab.frame.addEventListener("urlchange", (event) => {
            const current = event.url ? String(event.url) : "";
            if (current) {
              tab.url = current;
              tab.title = new URL(current).hostname.replace(/^www\./, "");
              if (tab.id === activeTabId) $("address").value = current;
              renderTabs();
              recordVisit(current);
            }
          });
        }
      }
      tabs.forEach((entry) => { if (entry.iframe) entry.iframe.style.display = entry.id === tab.id ? "block" : "none"; });
      activeTabId = tab.id;
      tab.url = url;
      tab.title = new URL(url).hostname.replace(/^www\./, "");
      $("address").value = url;
      renderTabs();
      $("newtab-home").classList.add("hidden");
      setProxyStatus("Loading website…", true);
      recordVisit(url);
      const navigation = tab.frame.go(url);
      if (navigation && typeof navigation.then === "function") await navigation;
    } catch (error) {
      console.error("Clever proxy error:", error);
      setProxyStatus("Proxy error: " + error.message, false);
      notify("Proxy failed: " + error.message);
    }
  }
  $("address-form").addEventListener("submit", (event) => {
    event.preventDefault();
    openUrl($("address").value, true);
  });
  $("go-back").addEventListener("click", () => { const tab = currentTab(); if (tab && tab.frame && tab.frame.back) tab.frame.back(); });
  $("go-forward").addEventListener("click", () => { const tab = currentTab(); if (tab && tab.frame && tab.frame.forward) tab.frame.forward(); });
  $("go-reload").addEventListener("click", () => { const tab = currentTab(); if (tab && tab.frame && tab.frame.reload) tab.frame.reload(); else if (tab && tab.url) openUrl(tab.url, true); });
  $("go-home").addEventListener("click", newTab);
  $("exit-fullscreen").addEventListener("click", () => setImmersive(false));
  function cloakCurrentSiteInRealTab() {
    const current = currentTab();
    const target = current && current.url ? current.url : "";
    if (!target) { notify("Open a website first, then use Cloak (new tab)."); return; }
    const destination = new URL(target);
    const cloakPage = new URL(location.href);
    cloakPage.search = "";
    cloakPage.hash = "";
    cloakPage.searchParams.set("cloak", "1");
    cloakPage.searchParams.set("url", target);
    const popup = window.open("about:blank", "_blank");
    if (!popup) { notify("Your browser blocked the new tab. Allow pop-ups for Clever and try again."); return; }
    const safeTitle = destination.hostname.replace(/^www\./, "");
    popup.document.open();
    popup.document.write('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + safeTitle.replace(/[<>&"]/g, "") + '</title><link rel="icon" href="https://www.google.com/s2/favicons?domain=' + encodeURIComponent(destination.hostname) + '&sz=64"><style>*{box-sizing:border-box}html,body,iframe{margin:0;width:100%;height:100%;border:0;background:#080a0f;display:block}</style></head><body><iframe allow="fullscreen; autoplay; clipboard-read; clipboard-write" referrerpolicy="no-referrer" src="' + cloakPage.href.replace(/&/g,"&amp;").replace(/"/g,"&quot;") + '"></iframe></body></html>');
    popup.document.close();
    renderPage("Browse");
    setBrowserVisible(false);
    setImmersive(false);
  }
  $("new-tab").addEventListener("click", cloakCurrentSiteInRealTab);
  $("top-newtab").addEventListener("click", cloakCurrentSiteInRealTab);
  function openFullscreenSearch() {
    $("fullscreen-search").classList.add("open");
    $("fullscreen-search").setAttribute("aria-hidden","false");
    setTimeout(() => $("fullscreen-query").focus(), 40);
  }
  function closeFullscreenSearch() {
    $("fullscreen-search").classList.remove("open");
    $("fullscreen-search").setAttribute("aria-hidden","true");
  }
  $("top-search").addEventListener("click", openFullscreenSearch);
  $("search-dismiss").addEventListener("click", closeFullscreenSearch);
  $("fullscreen-search").addEventListener("click", (event) => { if (event.target === $("fullscreen-search")) closeFullscreenSearch(); });
  $("fullscreen-search-form").addEventListener("submit", (event) => {
    event.preventDefault(); const query = $("fullscreen-query").value; closeFullscreenSearch(); openUrl(query, true);
  });
  $("newtab-search").addEventListener("submit", (event) => { event.preventDefault(); openUrl($("newtab-query").value, true); });
            document.querySelectorAll("[data-page]").forEach((button) => button.addEventListener("click", () => {
    setBrowserVisible(false);
    renderPage(button.dataset.page);
  }));
            document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      if ($("modal-scrim").classList.contains("show")) hideShortcutDialog();
      else closeFullscreenSearch();
    }
  });
  const cloakParams = new URLSearchParams(location.search);
  const cloakTarget = cloakParams.get("cloak") === "1" ? cloakParams.get("url") : "";
  if (cloakTarget) {
    document.title = new URL(cloakTarget).hostname.replace(/^www\./, "");
    $("app").classList.add("cloak-mode");
  }
  renderPage("Browse");
  setBrowserVisible(true);
  newTab();
  if (cloakTarget) {
    openUrl(cloakTarget, true);
  }
})();
